export const catalogs: Record<Locale, Catalog> = { pt, en, es };
export const localeCode: Record<Locale, string> = { pt: "pt-BR", en: "en-US", es: "es-US" };
export function translate(locale: Locale, key: TranslationKey, variables: Record<string, string | number> = {}) {
  return Object.entries(variables).reduce((text, [name, value]) => text.replaceAll(`{${name}}`, String(value)), catalogs[locale][key]);
}
